// Schema Check + Defaults (SAFE) — SW2  • v0.3.2 (pose library path + pose01 filenames)
// Normalize flags, compute pose/base keys & URLs, mirror identity & refs,
// ensure QA containers exist, and mark if we must fetch the pose image.
// Do NOT throw just because $binary.pose is missing; we’ll fetch it with an HTTP node when needed.

const jIn = $json || {};
const b   = $binary || {};

// ---------- helpers ----------
const num  = (v,d)=>Number.isFinite(+v)?+v:d;
const pick = (...v)=>v.find(x=>x!==undefined&&x!==null&&x!=='');
const toArr = (v)=>Array.isArray(v)?v:(v?[v]:[]);

// robust boolean coercion (treats "false","0","no","off" as false)
function asBool(v){
  if (v === true) return true;
  if (v === false || v == null) return false;
  if (typeof v === 'number') return v === 1;
  if (typeof v === 'string') {
    const s = v.trim().toLowerCase();
    if (/^(true|1|yes|y|on)$/.test(s))  return true;
    if (/^(false|0|no|n|off)$/.test(s)) return false;
    return false;
  }
  return false;
}

const pad2 = n => String(Number(n)).padStart(2,'0');

// ---------- flags / route (JSON-only, typed) ----------
const routeStr = String(jIn.__route || '').trim().toUpperCase();
const routeSaysTest = routeStr === 'TEST';
const routeSaysReal = routeStr === 'REAL';

const flagCandidates = [
  jIn.__testMode, jIn.testMode,
  jIn.__meta?.__testMode,
  jIn.ctx?.__testMode, jIn.ctx?.testMode
];

let isTest = routeSaysTest ? true
          : routeSaysReal ? false
          : flagCandidates.some(asBool);

const route  = routeSaysTest ? 'TEST'
            : routeSaysReal ? 'REAL'
            : (isTest ? 'TEST' : 'REAL');

// ---------- defaults & context ----------
const assetsRoot   = jIn.assetsRoot   || 'book-mvp-simple-adventure/order-generated-assets';
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url  = jIn.publicR2Url  || null;

// NEW: centralized pose library (matches your storage)
const poseLibraryRoot = (jIn.poseLibraryRoot || 'book-mvp-simple-adventure/characters/poses').replace(/\/+$/,'');

// Keep templatePath only for legacy overrides that already provide poseRefKey
const templatePath = jIn.templatePath || 'templates';

const ctx = jIn.ctx || {};
const characterHash = pick(jIn.characterHash, ctx.characterHash, jIn.__meta?.characterHash);

// ---------- pose identity ----------
const poseNum = num(pick(jIn.poseNumber, jIn.currentPoseNumber, jIn.pose?.poseNumber), null);

// ---------- compute poseRefKey / poseRefPublicUrl ----------
// Filename format is pose01.png (no hyphen)
const poseFileName = Number.isFinite(poseNum) ? `pose${pad2(poseNum)}.png` : null;

// Priority: explicit jIn.poseRefKey → else build from poseLibraryRoot
// (templatePath is retained only for legacy callers that already pass poseRefKey)
const poseRefKey = jIn.poseRefKey
  || (poseFileName ? `${poseLibraryRoot}/${poseFileName}` : null);

// UPDATE: Only construct if publicR2Url is available (use signed URL API for external access)
const poseRefPublicUrl = jIn.poseRefPublicUrl
  || (poseRefKey && publicR2Url ? `${publicR2Url}/${poseRefKey}` : null);

// ---------- base character keys/urls (for Style QA rehydration) ----------
const baseCharacterKey = jIn.baseCharacterKey
  || jIn.__meta?.baseUploadKey
  || jIn.__meta?.storageKey
  || (characterHash ? `${assetsRoot}/characters/${characterHash}/base-character.png` : null);

// UPDATE: Only construct if publicR2Url is available (use signed URL API for external access)
const baseRefPublicUrl = jIn.baseRefPublicUrl
  || (baseCharacterKey && publicR2Url ? `${publicR2Url}/${baseCharacterKey}` : null);

// ---------- decide if we need to fetch the pose image now ----------
const havePoseBinary =
  !!b.pose ||
  !!b.poseRef ||
  !!b.image_pose;

const needsPoseFetch = !havePoseBinary && !!poseRefPublicUrl;

// ---------- thresholds (lock at 0.75 unless provided) ----------
const qaThreshold       = num(jIn.qaThreshold,       0.75);
const styleQaThreshold  = num(jIn.styleQaThreshold,  0.75);
const colorQaThreshold  = num(jIn.colorQaThreshold,  0.75);

// ---------- normalize hairPromptMeta to an object ----------
let hairPromptMeta = jIn.hairPromptMeta;
if (typeof hairPromptMeta === 'string') {
  try { hairPromptMeta = JSON.parse(hairPromptMeta); } catch { hairPromptMeta = {}; }
}
if (!hairPromptMeta || typeof hairPromptMeta !== 'object') hairPromptMeta = {};

// ---------- mirror identity / correlation / retry crumbs ----------
const correlationId = pick(jIn.correlationId, jIn.__meta?.correlationId);
const amazonOrderId = pick(jIn.amazonOrderId, jIn.orderId);
const retryAttempt  = Number.isFinite(Number(jIn.retryAttempt)) ? Number(jIn.retryAttempt)
                    : Number.isFinite(Number(jIn.qaRetry))      ? Number(jIn.qaRetry)
                    : 0;
const retryTag      = pick(jIn.retryTag);

// ---------- ensure QA containers exist (non-breaking) ----------
const qaIn  = jIn.qa || {};
const qaOut = {
  pose:    qaIn.pose    || {},              // derive node will fill pass/score
  style:   qaIn.style   || { ran: false },  // style pipeline may fill later
  combined: qaIn.combined || { pass: false, policy: 'pose_then_style' },
};

// ---------- normalize reasons to arrays (if present) ----------
const qaReasons       = toArr(jIn.qaReasons);
const styleQaReasons  = toArr(jIn.styleQaReasons);

// ---------- emit ----------
const out = {
  ...jIn,
  ctx: { ...ctx, characterHash },
  assetsRoot, publicR2Url,
  // expose for transparency
  poseLibraryRoot,
  templatePath, // legacy visibility only
  characterHash,
  poseNumber: poseNum,
  currentPoseNumber: poseNum,
  poseRefKey,
  poseRefPublicUrl,
  baseCharacterKey,
  baseRefPublicUrl,
  correlationId,
  amazonOrderId,
  retryAttempt,
  retryTag,
  hairPromptMeta,
  qaThreshold, styleQaThreshold, colorQaThreshold,
  qaReasons, styleQaReasons,
  qa: qaOut,
  __testMode: isTest, testMode: isTest, __route: route,
  __meta: { ...(jIn.__meta || {}), sw2Entry: true, timestamp: new Date().toISOString() },
  __ensurePose: { needsPoseFetch }
};

// Do NOT block here; let a following IF/HTTP fetch the pose if needed
return [{ json: out, binary: b }];

// Style QA — Build Request — v2.7
// (hair locks = hard gate; base-only hair color; strict numeric skin-tone HSV; hidden extra-limb guard)
// Backward-compatible: prior fields preserved; adds numeric skin fields for downstream verification.

const j = $json || {};
const b = $binary || {};
const ix = (typeof $itemIndex === 'number') ? $itemIndex : 0;

const STRICT_ASSERT = true;

/* ------------ helpers ------------ */
function isImageBin(x){
  if (!x) return false;
  const mt = (x.mimeType || x.mimetype || '').toLowerCase();
  return typeof mt === 'string' && mt.startsWith('image/');
}
function parseSize(bin){
  const n = Number(bin?.fileSize);
  if (Number.isFinite(n)) return n;
  const d = bin?.data;
  if (typeof d === 'string') return d.length;
  if (Buffer.isBuffer(d)) return d.length;
  return 0;
}
async function keyToB64(key){
  if (!b[key]) return null;
  let buf = null;
  try { buf = await this.helpers.getBinaryDataBuffer(ix, key); } catch {}
  if (!buf) {
    try { buf = await this.helpers.getBinaryDataBuffer(key); } catch {}
  }
  if (buf) return buf.toString('base64');
  const d = b[key].data;
  if (typeof d === 'string') return d;
  if (Buffer.isBuffer(d)) return d.toString('base64');
  return null;
}
function keyMime(key){ return (b[key]?.mimeType || b[key]?.mimetype || 'image/png'); }
function firstDefined(){ for (let i=0;i<arguments.length;i++){ const v=arguments[i]; if (v!==undefined && v!==null && v!=='') return v; } }
function pad2(n){ n = Number(n); return Number.isFinite(n) ? String(n).padStart(2,'0') : '01'; }
function clampInt(v, lo=1, hi=99){ const n=Number(v); return Number.isFinite(n)?Math.max(lo,Math.min(hi,Math.floor(n))):null; }
function parsePoseFromString(s){
  if (!s) return null;
  const str=String(s);
  const m1 = str.match(/pose[_-]?(\d{1,2})(?:\.(?:png|jpe?g|webp))?$/i);
  const m2 = str.match(/(^|[^0-9])(\d{1,2})(?:\.(?:png|jpe?g|webp))?$/i);
  return m1 ? clampInt(m1[1]) : (m2 ? clampInt(m2[2]) : null);
}
function toPlainPoseNN(val, poseNumber){
  if (Number.isFinite(poseNumber)) return `pose${pad2(poseNumber)}`;
  if (!val) return undefined;
  const s = String(val).toLowerCase();
  const m = s.match(/pose[_-]?(\d{1,2})/i);
  return m ? `pose${pad2(Number(m[1]))}` : undefined;
}

/* ------------ resolve BASE (character) ------------ */
const baseKey = b.character ? 'character' : (b.base ? 'base' : null);
if (!baseKey) throw new Error('Style QA: missing character (base) binary');

const characterB64 = await keyToB64.call(this, baseKey);
if (!characterB64) throw new Error('Style QA: character binary had no data');

/* ------------ resolve GENERATED (OUTPUT) ------------ */
const EXCLUDE_KEYS = new Set(['pose','poseRef','image_pose','P','A','pose_ref']);
const PREFERRED_GEN_KEYS = [
  'generated','final_generated','generated_inline',
  'output','result','image','image_output','data','file','content'
];

let genKey = null;
for (const k of PREFERRED_GEN_KEYS) {
  if (isImageBin(b[k])) { genKey = k; break; }
}
if (!genKey) {
  const excludeAlso = new Set([...EXCLUDE_KEYS, baseKey, 'hair']);
  let best = null;
  for (const [k, bin] of Object.entries(b)) {
    if (excludeAlso.has(k)) continue;
    if (!isImageBin(bin)) continue;
    const size = parseSize(bin);
    if (!best || size > best.size) best = { k, size };
  }
  genKey = best?.k || null;
}
if (!genKey) throw new Error('Style QA: missing generated image binary');

const generatedB64 = await keyToB64.call(this, genKey);
if (!generatedB64) throw new Error('Style QA: generated binary had no data');

/* ------------ optional HAIR (IMAGE B) ------------ */
const hairKey = isImageBin(b.hair) ? 'hair'
  : (isImageBin(b.hair_chip) ? 'hair_chip'
  : (isImageBin(b.hairRef) ? 'hairRef' : null));
const hairB64 = hairKey ? await keyToB64.call(this, hairKey) : null;

/* ------------ identity mirrors (LEAN) ------------ */
const characterHash     = firstDefined(j.characterHash, j.character_hash, j.character?.hash);
const poseNumberRaw     = firstDefined(j.poseNumber, j.expectedPoseNumber, j.pose_index);
let   poseNumber        = Number.isFinite(Number(poseNumberRaw)) ? Number(poseNumberRaw) : null;
if (!Number.isFinite(poseNumber)) {
  poseNumber = parsePoseFromString(j.generatedFileName)
            ?? parsePoseFromString(b[genKey]?.fileName)
            ?? (Number.isFinite(Number(j.index)) ? Number(j.index) + 1 : null);
}

const poseNN_plain   = toPlainPoseNN(j.poseNN || j.poseNN_hyphen, poseNumber) 
                    || (Number.isFinite(poseNumber) ? `pose${pad2(poseNumber)}` : undefined);
const poseNN_hyphen  = poseNN_plain ? poseNN_plain.replace(/^pose(\d{2})$/,'pose-$1') : undefined;

const generatedFileName = firstDefined(j.generatedFileName, b[genKey]?.fileName, b[genKey]?.fileNameOriginal);

/* ------------ thresholds (pass-through) ------------ */
const qaThreshold       = Number.isFinite(+j.qaThreshold)      ? +j.qaThreshold      : 0.75;
const styleQaThreshold  = Number.isFinite(+j.styleQaThreshold) ? +j.styleQaThreshold : 0.75;
const colorQaThreshold  = Number.isFinite(+j.colorQaThreshold) ? +j.colorQaThreshold : 0.75;

/* ------------ system instruction (v2.7: roles by index + numeric skin) ------------ */
const systemText = `You are a validator for a vector character illustration.

IMAGE ROLES (by inline image index in the user message):
- #1 = BASE (character; authoritative palette & hair color)
- #2 = OUTPUT (generated; to be judged)
- #3 (if present) = IMAGE B (hair silhouette reference ONLY; ignore its color)
Never infer roles from any text labels; use only inline image order.

Return ONLY JSON (no prose). If uncertain, be stricter (lower scores/FAIL). Do NOT judge pose matching. You MUST detect anatomical count errors (extra/missing/duplicated hands/arms/legs/feet).

TEXTURE (must match BASE):
- Detect subtle paper-grain texture and soft shading. OUTPUT must match: paper grain present vs not present.

CRITICAL HAIR RULES — any violation forces FAIL (apply all below):
1) LENGTH LOCK: SHORT (above chin) / MEDIUM (at shoulders) / LONG (below shoulders). If different vs BASE ⇒ FAIL.
2) STYLE LOCK: LOOSE/FLOWING vs PULLED-BACK (ponytail/pigtails) vs UP-DO (bun) vs PUFF/AFRO vs LOCS. If different ⇒ FAIL.
3) SILHOUETTE INTEGRITY: Hair must be one solid contiguous mass (no islands/holes). Any separated strand/wisp/halo/cluster ⇒ stray_hairs_present=true and FAIL.

On any hair FAIL set:
- "hair_cleanliness_score": 0
- "hair_silhouette_solid": false
- "stray_hairs_present": true (and "stray_hair_count" ≥ 1)
- "identity_score": 0
- "style_score": 0
- "notes": include which hair rule failed and why.

HAIR COLOR:
- Compare OUTPUT hair color to BASE only (ignore IMAGE B color).
- Perfect match=1.0; noticeable hue/value shift or missing hair=0.0–0.25.

SKIN TONE (HSV; deterministic sampling; NUMERIC OUTPUTS REQUIRED; no qualitative phrases):
- Visible skin only (face/neck/arms). Ignore lips, blush/makeup, nose triangle, deep shadow, highlights.
- ROI priority (first available; use the same site in both images): left cheek mid-face → right cheek → forehead center (avoid specular) → inner forearm → back of hand.
- Use a flat midtone patch (~25×25 px equivalent).
- Compute absolute percentage-point deltas:
  ΔS% = |S_out − S_base| × 100
  ΔV% = |V_out − V_base| × 100
- PASS iff (ΔV≤8 AND ΔS≤12). Do not write “exact match”; output numbers only.
- If no valid ROI OR metrics cannot be computed: set "skin_evaluable": false, "skin_pass": false, and "skin_tone_score" ≤ 0.45. Still fill numeric fields with 0.00 where undefined.

ANATOMY COUNT (not pose matching):
- Expect exactly 2 arms (max 2 wrists/hands) and 2 legs (max 2 feet/shoes).
- If extra/missing/duplicated limb element is clearly present ⇒ "identity_score": 0 and "style_score": ≤ 0.25; include "extra limb" in notes (prefer false negatives over false positives). In poses where one or both arms are raised, be extra sure that there are no extra hanging arms that should not exist. EXACTLY one arm on each side of the body.

Return ONLY this JSON with EXACT property names and numeric constraints (no percent signs, no qualitative terms):
{
  "identity_score": 0.0-1.0,
  "identity_match": true/false,

  "style_score": 0.0-1.0,
  "line_style_match": true/false,

  "color_score": 0.0-1.0,

  "hair_color_score": 0.0-1.0,
  "hair_color_match": true/false,

  "skin_tone_score": 0.0-1.0,
  "skin_pass": true/false,
  "skin_evaluable": true/false,
  "skin_roi": "left_cheek|right_cheek|forehead|forearm|hand|none",
  "skin_s_base": 0.00-1.00,
  "skin_v_base": 0.00-1.00,
  "skin_s_out":  0.00-1.00,
  "skin_v_out":  0.00-1.00,
  "skin_ds_pct": 0.0-100.0,    // absolute percentage points
  "skin_dv_pct": 0.0-100.0,    // absolute percentage points

  "clothing_score": 0.0-1.0,

  "hair_cleanliness_score": 0.0-1.0,
  "hair_silhouette_solid": true/false,
  "stray_hairs_present": true/false,
  "stray_hair_count": 0-50,

  "notes": "one brief sentence on the biggest mismatch (if any); include 'skin ΔV≈x, ΔS≈y' as numbers only"
}

Consistency rules:
- Even if hair FAILS, still compute and return the skin fields above.
- Set "skin_tone_score" in [0.95, 1.00] only when "skin_pass" = true; otherwise set ≤ 0.45.`;

/* ------------ build parts (BASE=#1, OUTPUT=#2, optional HAIR=#3) ------------ */
const parts = [
  {
    text:
      "Validate identity, style, color, strict skin tone (HSV), clothing, HAIR CLEANLINESS, and ANATOMY COUNT. " +
      "IMAGE ROLES by inline image index: #1=BASE, #2=OUTPUT, #3 (optional)=IMAGE B (hair silhouette only). " +
      "Do NOT judge pose matching."
  },
  { inlineData: { mimeType: keyMime(baseKey), data: characterB64 } },   // #1 BASE
  { inlineData: { mimeType: keyMime(genKey),  data: generatedB64 } },   // #2 OUTPUT
  ...(hairB64 ? [{ inlineData: { mimeType: keyMime(hairKey), data: hairB64 } }] : []) // #3 HAIR (optional)
];

// structure self-check
const kinds = parts.map(p => p.inlineData ? 'inlineData' : 'text');
const expectedNoHair   = ['text','inlineData','inlineData'];
const expectedWithHair = ['text','inlineData','inlineData','inlineData'];
const expected = hairB64 ? expectedWithHair : expectedNoHair;

const partsSummary = {
  length: parts.length,
  kinds,
  expected,
  hasBase: true,
  hasOutput: true,
  hasHair: !!hairB64,
  baseKeyUsed: baseKey,
  generatedKeyUsed: genKey,
  hairKeyUsed: hairKey || null,
  roleByIndex: { "1":"BASE(character)", "2":"OUTPUT(generated)", ...(hairB64 ? {"3":"IMAGE_B(hair only)"} : {}) },
  poseNN_plain: (toPlainPoseNN(j.poseNN || j.poseNN_hyphen, poseNumber)) || null,
  poseNN_hyphen: ((toPlainPoseNN(j.poseNN || j.poseNN_hyphen, poseNumber)) || '').replace(/^pose(\d{2})$/,'pose-$1') || null,
};

if (STRICT_ASSERT && JSON.stringify(kinds) !== JSON.stringify(expected)) {
  throw new Error(`Style QA Build Request: parts order mismatch. Got ${JSON.stringify(kinds)} expected ${JSON.stringify(expected)}.`);
}

/* ------------ Gemini request body ------------ */
const qaRequestBody = {
  systemInstruction: { parts: [{ text: systemText }] },
  contents: [{ role: 'user', parts }],
  generationConfig: { temperature: 0.0, responseMimeType: 'application/json' },
};

/* ------------ emit (pose binaries dropped; OUT = LEAN) ------------ */
const corrIn = firstDefined(j.correlationId, j.correlation_id);
const correlationId = (typeof corrIn === 'string' && corrIn.includes('-POSE'))
  ? corrIn.replace('-POSE', '-STYLE')
  : (corrIn || `style-qa-${Date.now()}-${ix}`);

const droppedPoseKeys = Object.keys(b).filter(k => /^pose($|_|-|Ref)/i.test(k));
const approxBodyBytes = Buffer.byteLength(JSON.stringify(qaRequestBody), 'utf8');

const out = {
  correlationId,
  characterHash,
  poseNumber: Number.isFinite(poseNumber) ? poseNumber : undefined,
  poseNN: toPlainPoseNN(j.poseNN || j.poseNN_hyphen, poseNumber),
  poseNN_hyphen: (toPlainPoseNN(j.poseNN || j.poseNN_hyphen, poseNumber) || '').replace(/^pose(\d{2})$/,'pose-$1') || undefined,
  generatedFileName,

  // thresholds (unchanged schema)
  qaThreshold,
  styleQaThreshold,
  colorQaThreshold,

  // request body for HTTP node
  qaType: 'style',
  qaContractVersion: 'styleqa@2.7', // roles by index + numeric skin fields
  qaRequestBody,

  __meta: {
    ...(j.__meta || {}),
    styleQaBuildRequest: {
      droppedPoseKeys,
      approxBodyBytes,
      partsSummary,
    },
  },
};

const outBin = {
  character: b[baseKey],
  generated: b[genKey],
  ...(hairKey ? { hair: b[hairKey] } : {}),
};

return {
  json: out,
  binary: outBin,
  pairedItem: ($input?.item?.pairedItem) ? $input.item.pairedItem : { item: ix },
};

// 🧪 MOCK: Style QA - Always PASS
// Returns a passing style/color QA verdict for testing

const j = $json || {};

const mockPoseScore = Number.isFinite(Number(j.mockStyleScore)) ? Number(j.mockStyleScore) : 0.95;
const mockColorScore = Number.isFinite(Number(j.mockColorScore)) ? Number(j.mockColorScore) : 0.93;

const verdictObject = {
  style_score: mockPoseScore,
  color_score: mockColorScore,
  line_style_match: true,
  palette_shift: false,
  saturation_shift: false,
  skin_tone_match: true,
  hair_color_match: true,
  notes: 'Mock Style QA - test mode always passes'
};

const mockResponse = {
  candidates: [{
    content: {
      parts: [{
        text: JSON.stringify(verdictObject)
      }]
    },
    finishReason: "STOP"
  }],
  usageMetadata: {
    promptTokenCount: 50,
    candidatesTokenCount: 20,
    totalTokenCount: 70
  }
};

console.log('🧪 MOCK STYLE QA PASS emitted, style_score:', mockPoseScore, 'color_score:', mockColorScore);

return {
  json: mockResponse,
  binary: $binary,
  pairedItem: ($input?.item?.pairedItem) ? $input.item.pairedItem : { item: ($itemIndex ?? 0) }
};

// Parse Style QA Verdict — v2.7
// Adds numeric skin fields (skin_pass/evaluable/roi + S/V + ΔS/ΔV) and enforces a local clamp:
// - If metrics invalid or unevaluable => skin_pass=false, skin_tone_score<=0.45
// - If metrics valid and pass => skin_tone_score in [0.95,1.00]
// Back-compat with pre-2.7 payloads.

const j  = $json || {};
const b  = $binary || {};
const ix = (typeof $itemIndex === 'number') ? $itemIndex : 0;
const rx = (typeof $runIndex === 'number') ? $runIndex : 0;

/* ---------------- helpers ---------------- */
function firstDefined(...vals){ for (const v of vals){ if (v !== undefined && v !== null && v !== '' ) return v; } }
function clamp(v, lo, hi){ const n = Number(v); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : n; }
function toNum01(x, d=undefined){ const n = Number(x); return Number.isFinite(n) ? Math.max(0, Math.min(1, n)) : d; }
function toNumRange(x, lo, hi, d=undefined){ const n = Number(x); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; }
function toBoolStrict(x){
  if (x === true || x === false) return x;
  if (typeof x === 'string'){
    const s = x.trim().toLowerCase();
    if (['true','1','yes','y','on'].includes(s))  return true;
    if (['false','0','no','n','off'].includes(s)) return false;
  }
  if (x === 1) return true;
  if (x === 0) return false;
  return undefined;
}
function findText(obj) {
  if (!obj || typeof obj !== 'object') return null;
  if (typeof obj.text === 'string') return obj.text;
  if (Array.isArray(obj.parts)) {
    for (const p of obj.parts) {
      const t = findText(p);
      if (t) return t;
    }
  }
  if (obj.content) return findText(obj.content);
  if (Array.isArray(obj.candidates)) {
    for (const c of obj.candidates) {
      const t = findText(c);
      if (t) return t;
    }
  }
  return null;
}
function stripInlineDataDeep(obj){
  if (!obj || typeof obj !== 'object') return;
  if (obj.inlineData && typeof obj.inlineData === 'object') {
    if (typeof obj.inlineData.data === 'string') {
      delete obj.inlineData.data;
      obj.inlineData.stripped = true;
    }
  }
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (v && typeof v === 'object') stripInlineDataDeep(v);
  }
}
function getSameRunItem(name){
  try{
    const arr = $items(name, 0, rx);
    return (Array.isArray(arr) && arr[ix]) ? arr[ix] : null;
  }catch{ return null; }
}

/* ---------------- parse verdict (robust) ---------------- */
let verdict = {};
let parseOk = false;
let rawText = '';

const candidateObj = (typeof j === 'object' && j) || {};
const hasDirect =
  ('identity_score' in candidateObj) ||
  ('identity_match' in candidateObj) ||
  ('style_score' in candidateObj) ||
  ('line_style_match' in candidateObj) ||
  ('color_score' in candidateObj) ||
  ('hair_color_score' in candidateObj) ||
  ('hair_color_match' in candidateObj) ||
  ('skin_tone_score' in candidateObj) ||
  ('clothing_score' in candidateObj) ||
  ('hair_cleanliness_score' in candidateObj) ||
  ('hair_silhouette_solid' in candidateObj) ||
  ('stray_hairs_present' in candidateObj) ||
  ('stray_hair_count' in candidateObj) ||
  ('skin_pass' in candidateObj) || ('skin_evaluable' in candidateObj) ||
  ('skin_ds_pct' in candidateObj) || ('skin_dv_pct' in candidateObj);

if (hasDirect) {
  verdict = candidateObj;
