// Derive QA Pass — v5.2 (retry-aware, pre-slim, size-budget, robust verdict parsing)
// - Pre-slims input BEFORE spreading to avoid transient OOM
// - Preserves retryAttempt/retryTag
// - Emits compact qaHints + qaNotes for retry builder
// - Parses stringified qaVerdict; coerces boolean-like strings; de-dupes reasons; adds qaPoseRan
// - NEW: writes qa.pose { pass, ran, threshold, score, reasons, notes, flags }, plus poseQaPass/poseQaScore
// - NEW: includes 'qa' in size-guard allow list so qa.pose is retained if we have to slim

const item = $input.item || { json: {}, binary: {} };
const b    = item.binary || {};
const jRaw = item.json || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;
const ix    = (typeof $itemIndex === 'number') ? $itemIndex : 0;

/* ------------ config ------------ */
const MAX_JSON_BYTES   = Number.isFinite(Number(jRaw.__qaMaxBytes)) ? Number(jRaw.__qaMaxBytes) : 120 * 1024; // 120KB
const LARGE_STR_THRESH = 4096; // strip suspicious base64-ish strings above this length by key hint
const KEEP_PAIRED_ITEM = jRaw.__keepPairedItem === true; // default false to reduce memory

/* ------------ helpers ------------ */
function firstDefined(...vals){ for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; } return undefined; }
function toNum(x){ const n = Number(x); return Number.isFinite(n) ? n : undefined; }
function pad2(n){ n = Number(n); return Number.isFinite(n) ? String(n).padStart(2,'0') : '01'; }
