        poseNN: poseNN ?? null,
        poseKey: poseKey ?? null,
        retryAttempt: retryAttempt ?? null,
        retryTag: retryTag ?? null,
        orderContext: jSlim.orderContext ?? null,
        orderData: jSlim.orderData ?? null
