};

/* ------------ add stable qa.pose + mirrors ------------ */
const existingQa = (typeof jSlim.qa === 'object' && jSlim.qa) ? { ...jSlim.qa } : {};
existingQa.pose = {
  pass: qaPass,
  ran: true,
  threshold: thr,
  score: Number.isFinite(score) ? Number(score) : null,
  reasons,
  notes: (typeof out.qaNotes === 'string') ? out.qaNotes : undefined,
  // expose the individual boolean flags for debugging/analytics
  single_subject: vFlags.single_subject ?? null,
  extra_limbs:    vFlags.extra_limbs ?? null,
  bg_white:       vFlags.bg_white ?? null,
  leakage_from_pose_ref: vFlags.leakage_from_pose_ref ?? null,
