// explicit mirrors (for compatibility)
out.poseQaPass  = qaPass;
out.poseQaScore = Number.isFinite(score) ? Number(score) : null;

/* ------------ prune heavy known keys (defensive) ------------ */
const PRUNE_TOP = [
  'qaRequestBody','systemInstruction','contents','candidates','usageMetadata',
  'vertexResponse','rawResponse','raw','fullResponse','imagePrompt','promptParts',
  'payload','result','response','debug','__raw','text','explanations','body','data'
];
