    // identities / routing
    'amazonOrderId','orderId','rootOrderId','root_order_id','correlationId','characterHash','poseNumber','poseNN','poseIndex','poseKey',
    'generatedFileName','expectedPoseNumber','orderDate',
    // QA outputs
    'qaPoseRan','qaPass','qaReasons','qaThreshold','qaScore','qaVerdict','qaHints','qaNotes',
    // mirrors
    'poseQaPass','poseQaScore',
    // retry
    'retryAttempt','retryTag','qaRetry',
    // structured QA (keep!)
    'qa',
    // small meta (includes our snapshot)
    '__meta'
  ];
