const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

/* ----------------- helpers ----------------- */
function get(obj, path){
  let cur = obj; for (const k of path){ if (cur == null) return undefined; cur = cur[k]; }
  return cur;
}
function firstDefined(){ for (let i=0;i<arguments.length;i++){ const v = arguments[i]; if (v !== undefined && v !== null && v !== '') return v; } }
function asInt(v){ const n=Number(v); return Number.isFinite(n)?Math.floor(n):null; }
